package mr

import (
	"sync/atomic"
	"testing"
	"time"
)

func poolCheck(t *testing.T, n, jobsN int) {
	var active, peak int32
	f := func(x int) int {
		a := atomic.AddInt32(&active, 1)
		for {
			p := atomic.LoadInt32(&peak)
			if a <= p || atomic.CompareAndSwapInt32(&peak, p, a) {
				break
			}
		}
		time.Sleep(40 * time.Millisecond)
		atomic.AddInt32(&active, -1)
		return x * x
	}
	jobs := make([]int, jobsN)
	for i := range jobs {
		jobs[i] = i + 1
	}
	start := time.Now()
	res := RunPool(n, jobs, f)
	el := time.Since(start)
	if len(res) != jobsN {
		fail(t, "pool_order", say("应该返回 %d 个结果，实际返回了 %d 个。", "Should return %d results, returned %d.", jobsN, len(res)))
	}
	for i, j := range jobs {
		if res[i] != j*j {
			fail(t, "pool_order", say("results[%d] 应该是 f(%d) = %d，实际是 %d。结果的顺序要和 jobs 一致。", "results[%d] should be f(%d) = %d, got %d. Results must be in the same order as jobs.", i, j, j*j, res[i]))
		}
	}
	if int(peak) > n {
		fail(t, "pool_too_many", say("同一时刻最多应该有 %d 个 f 在运行，实际最多有 %d 个。", "At most %d calls of f should run at once; up to %d did.", n, peak))
	}
	if int(peak) < n {
		fail(t, "pool_serial", say("允许同时运行 %d 个，但最多只有 %d 个在同时运行，没有用满工作池。", "%d may run at once, but at most %d ran together; the pool was not used fully.", n, peak))
	}
	limit := time.Duration((jobsN+n-1)/n) * 40 * time.Millisecond * 18 / 10
	if el > limit {
		fail(t, "pool_slow", say("用了 %v，超过了 %v。", "Took %v, more than %v.", el.Round(time.Millisecond), limit))
	}
}

func TestLv2_PoolOf3(t *testing.T) { poolCheck(t, 3, 12) }
func TestLv2_PoolOf1(t *testing.T) { poolCheck(t, 1, 5) }
func TestLv2_PoolWide(t *testing.T) { poolCheck(t, 8, 8) }
